using System;
using System.Linq;
using NUnit.Framework;
using UnityEditor;
using UnityEditor.Animations;
using UnityEngine;
using DeadQuarantine.PvPvE;
using DeadQuarantine.PvPvE.Networking;
public class PvPvEAnimationAccessoryTests {
 static GameObject Player=>AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Player.prefab");
 static AnimatorController Base(RuntimeAnimatorController c)=>c is AnimatorOverrideController o?(AnimatorController)o.runtimeAnimatorController:(AnimatorController)c;
 static void AssertMotion(Motion a,Motion b){if(a is BlendTree x){Assert.IsInstanceOf<BlendTree>(b);var y=(BlendTree)b;Assert.AreEqual(x.blendParameter,y.blendParameter);Assert.AreEqual(x.blendType,y.blendType);Assert.AreEqual(x.children.Length,y.children.Length);for(int i=0;i<x.children.Length;i++){Assert.AreEqual(x.children[i].threshold,y.children[i].threshold);AssertMotion(x.children[i].motion,y.children[i].motion);}}else Assert.AreEqual(a,b);}
 [Test] public void AllWeaponVariantsKeepNetworkAnimatorTopology(){var n=Player.GetComponent<NetworkWeaponPresentation>();var reference=Base(n.Weapons[0].Controller);var parameters=reference.parameters.Select(p=>p.name+":"+p.type).ToArray();foreach(var d in n.Weapons){Assert.IsNotNull(d.Source.GetComponent<PackWeaponPresentation>(),d.Id+" persisted calibration component");var c=Base(d.Controller);Assert.AreEqual(reference.layers.Length,c.layers.Length,d.Id);CollectionAssert.AreEqual(parameters,c.parameters.Select(p=>p.name+":"+p.type).ToArray(),d.Id);}var sw=new SerializedObject(Player.GetComponentInChildren<WeaponSwitcher>(true));var slots=sw.FindProperty("slots");for(int i=0;i<slots.arraySize;i++){var c=(RuntimeAnimatorController)slots.GetArrayElementAtIndex(i).FindPropertyRelative("tpOverrideController").objectReferenceValue;if(c)Assert.AreEqual(reference.layers.Length,Base(c).layers.Length,"slot "+i);}}
 [TestCase("Handgun","Assets/Animations/ThirdPersonAnimator.controller")]
 [TestCase("Rifle","Assets/Animations/OverrideThirdPerson/OC_TP_Rifle.overrideController")]
 [TestCase("Escopeta","Assets/Animations/OverrideThirdPerson/OC_TP_Shotgun.overrideController")]
 public void ProtectedWeaponsKeepTheirOriginalEffectiveClips(string id,string path){var original=AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(path);var current=Player.GetComponent<NetworkWeaponPresentation>().Weapons.Single(d=>d.Id==id).Controller;CollectionAssert.AreEquivalent(original.animationClips,current.animationClips,id);var source=Base(original);var target=Base(current);for(int i=0;i<source.layers.Length;i++){Assert.AreEqual(source.layers[i].name,target.layers[i].name);Assert.AreEqual(source.layers[i].blendingMode,target.layers[i].blendingMode);var before=source.layers[i].stateMachine.states;var after=target.layers[i].stateMachine.states;Assert.AreEqual(before.Length,after.Length);foreach(var b in before){var a=after.Single(a=>a.state.name==b.state.name);AssertMotion(b.state.motion,a.state.motion);Assert.AreEqual(b.state.speed,a.state.speed);}}Assert.AreEqual(0,target.layers.Last().defaultWeight);}
 [Test] public void ProtectedAccessoriesAreValidPick10Classes(){var config=AssetDatabase.LoadAssetAtPath<PvPvENetworkSettings>("Assets/PvPvE/Settings/PvPvENetworkSettings.asset");foreach(var id in new[]{"Rifle","Escopeta"}){var c=config.Loadouts.Default(0);c.primary=id;c.secondary="Handgun";c.perk1=c.perk2=c.wildcard1=c.wildcard2="";c.primaryAttachments=new WeaponAttachmentChoice{scope="Scope_01",muzzle="Muzzle_Silencer_01"};c.secondaryAttachments=new WeaponAttachmentChoice{scope="Scope_02",muzzle="Muzzle_Silencer_01"};Assert.IsTrue(config.Loadouts.Validate(c,out var error),error);Assert.LessOrEqual(config.Loadouts.Pick10Cost(c),10);}}
 [Test] public void CopiedPackFireSourcesUseHumanoidAndOwnAvatar(){var guids=AssetDatabase.FindAssets("t:Model",new[]{"Assets/Generated/NewWeapons/Phase25/Source431"});Assert.Greater(guids.Length,0);foreach(var guid in guids){var importer=(ModelImporter)AssetImporter.GetAtPath(AssetDatabase.GUIDToAssetPath(guid));Assert.AreEqual(ModelImporterAnimationType.Human,importer.animationType);Assert.AreEqual(ModelImporterAvatarSetup.CreateFromThisModel,importer.avatarSetup);Assert.IsTrue(importer.clipAnimations.All(c=>c.hasAdditiveReferencePose));}}
}
